mapper.update:
UPDATE EAI.IF_SUPPLY_PO_SEND O
   SET O.IF_FLAG='D'
      ,O.DATA09=#{st_user_id}
      ,O.DATA10=#{resendReason}
 WHERE O.AGENT=#{st_agent}
   AND O.BUYER=#{st_buyer}
   AND O.PO_NO=#{st_po_no}
   AND O.PO_SEQ=#{st_po_seq}
   AND O.STATUS='C'
   AND O.REVISION=#{st_revision}
   AND O.PR_NO=#{st_pr_no}
   AND O.PR_SEQ=#{st_pr_seq}
   AND O.IF_FLAG IN('S','F')
   AND O.REVISION=(
       SELECT MAX(X.REVISION)
         FROM EAI.IF_SUPPLY_PO_SEND X
        WHERE X.BUYER=O.BUYER
          AND X.PR_NO=O.PR_NO
          AND X.PR_SEQ=O.PR_SEQ
   )
